function aw_user(array $u):string{return (string)($u['full_name']??$u['username']??'User');}
function aw_can_read(array $u):bool{return ($u['role']??'')==='Super Admin'||tt_user_can_open_module($u,'Accounts')||tt_user_can_open_module($u,'Directors');}
function aw_can_directors(array $u):bool{return ($u['role']??'')==='Super Admin'||tt_user_can_open_module($u,'Directors');}
