function aw_read():array{tt_ensure_data_dir();if(!is_file(AW_FILE))return aw_defaults();$h=fopen(AW_FILE,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);} $s=$raw?json_decode($raw,true):null;return is_array($s)?array_replace_recursive(aw_defaults(),$s):aw_defaults();}
function aw_save_handle($h,array &$s):void{$s['revision']=(int)($s['revision']??0)+1;rewind($h);if(!ftruncate($h,0))throw new RuntimeException('Could not update Accounts storage.');$raw=json_encode($s,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);if(fwrite($h,$raw)===false)throw new RuntimeException('Could not write Accounts storage.');fflush($h);}
function aw_entity(string $v,bool $tg=true):string{$v=strtoupper(trim($v));$ok=$tg?['TTI','BRM','TG']:['TTI','BRM'];if(!in_array($v,$ok,true))aw_out(['ok'=>false,'error'=>'Invalid entity.'],422);return $v;}
function aw_date(string $v,string $label):string{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$v))aw_out(['ok'=>false,'error'=>$label.' is required.'],422);return $v;}
function aw_num(mixed $v,string $label,bool $allowZero=false):float{$n=round((float)$v,3);if($n<0||(!$allowZero&&$n<=0))aw_out(['ok'=>false,'error'=>$label.' is invalid.'],422);return $n;}
function aw_id(array $rows,string $prefix):string{$n=count($rows)+1;do{$id=$prefix.'-'.gmdate('Y').'-'.str_pad((string)$n,5,'0',STR_PAD_LEFT);$n++;}while(isset($rows[$id]));return $id;}
function aw_audit(array &$s,string $type,string $id,string $action,array $u,array $before=[],array $after=[],string $reason=''):void{$s['workflowAudit'][]=['at'=>gmdate('c'),'type'=>$type,'id'=>$id,'action'=>$action,'user'=>aw_user($u),'reason'=>$reason,'before'=>$before,'after'=>$after];if(count($s['workflowAudit'])>5000)$s['workflowAudit']=array_slice($s['workflowAudit'],-5000);}
function aw_commodity(string $v,string $sub=''):array{$v=strtoupper(trim($v));$sub=strtoupper(trim($sub));if($v==='RICE')return ['RICE','RICE'];if(in_array($v,['CORN','MAIZE','MAKAI'],true))return ['CORN','CORN'];if($v==='SESAME')return ['SESAME',in_array($sub,['RAW','SESAME_RAW'],true)?'SESAME_RAW':'SESAME_READY'];aw_out(['ok'=>false,'error'=>'Commodity must be Rice, Corn / Makai or Sesame.'],422);}
function aw_soda_no(array $s,string $entity,string $commodity):string{$prefix=$commodity==='RICE'?'R':($commodity==='CORN'?'M':'S');$yy=gmdate('y');$max=0;foreach((array)$s['purchaseSodasV2'] as $x){if(!is_array($x)||($x['entity']??'')!==$entity||($x['commodity']??'')!==$commodity)continue;if(preg_match('/^'.$prefix.$yy.'-(\d{4})$/',(string)($x['sodaNo']??''),$m))$max=max($max,(int)$m[1]);}return $prefix.$yy.'-'.str_pad((string)($max+1),4,'0',STR_PAD_LEFT);}
function aw_receipts(array $s,array $soda):array{$out=[];$no=(string)$soda['sodaNo'];foreach((array)$s['events'] as $ev){if(!is_array($ev)||($ev['eventType']??'')!=='COMMODITY_RECEIPT_ACCEPTED'||($ev['entity']??'')!==$soda['entity'])continue;$j=$s['journals'][$ev['journalId']??'']??null;if(!is_array($j))continue;$m=is_array($j['meta']??null)?$j['meta']:[];if((string)($m['soda']??'')!==$no)continue;$date=(string)($j['date']??'');$out[]=['eventId'=>(string)($ev['id']??''),'sourceKey'=>(string)($ev['sourceKey']??''),'date'=>$date,'pohanch'=>(string)($m['pohanch']??$j['reference']??''),'truck'=>(string)($m['truck']??''),'kg'=>round((float)($m['payableWeightKg']??0),3),'amount'=>round((float)($j['totalDebit']??0),2),'billId'=>(string)($ev['billId']??''),'late'=>$date!==''&&$date>(string)$soda['arrivalDueDate']];}usort($out,fn($a,$b)=>strcmp($a['date'],$b['date']));return $out;}
function aw_soda_view(array $s,array $x):array{$r=aw_receipts($s,$x);$received=array_sum(array_column($r,'kg'));$min=(float)($x['qtyFromKg']??0);$max=(float)($x['qtyToKg']??0);$today=(new DateTimeImmutable('now',new DateTimeZone('Asia/Karachi')))->format('Y-m-d');$manual=(string)($x['manualStatus']??'');$status='Open';if(in_array($manual,['Cancelled','Short Closed','Manual Closed'],true))$status=$manual;elseif($min>0&&$received>=$min)$status=$max>0&&$received>=$max?'Fully Utilized':'Completed at Minimum Range';elseif($received>0)$status='Part Received';if(in_array($status,['Open','Part Received'],true)&&$today>(string)$x['arrivalDueDate'])$status='Overdue Balance';if(array_filter($r,fn($a)=>!empty($a['late']))&&!in_array($status,['Fully Utilized','Cancelled','Short Closed','Manual Closed'],true))$status='Needs Review';return $x+['receivedKg'=>round($received,3),'balanceToMinKg'=>round(max(0,$min-$received),3),'balanceToMaxKg'=>round(max(0,$max-$received),3),'calculatedStatus'=>$status,'receipts'=>$r,'lateCount'=>count(array_filter($r,fn($a)=>!empty($a['late']))),'canAcceptMore'=>$max<=0||$received<$max-0.001];}
function aw_sync_late_holds(array &$s):int{$late=[];$n=0;foreach((array)$s['purchaseSodasV2'] as $x){if(!is_array($x)||($x['manualStatus']??'')==='Cancelled')continue;foreach(aw_receipts($s,$x) as $r){if(empty($r['late'])||($r['sourceKey']??'')==='')continue;$k=$x['entity'].'|'.$r['sourceKey'];$late[$k]=true;$old=$s['payableHolds'][$k]??null;if(is_array($old)&&!empty($old['active'])&&empty($old['systemRule']))continue;$row=['entity'=>$x['entity'],'sourceKey'=>$r['sourceKey'],'active'=>true,'reason'=>'Late delivery after Soda arrival due date','systemRule'=>'LATE_DELIVERY','sodaNo'=>$x['sodaNo'],'pohanch'=>$r['pohanch'],'createdAt'=>(string)($old['createdAt']??gmdate('c')),'updatedAt'=>gmdate('c'),'createdBy'=>(string)($old['createdBy']??'System')];if($old!=$row){$s['payableHolds'][$k]=$row;$n++;}}}foreach((array)$s['payableHolds'] as $k=>$h){if(!is_array($h)||($h['systemRule']??'')!=='LATE_DELIVERY'||empty($h['active'])||isset($late[$k]))continue;$s['payableHolds'][$k]['active']=false;$s['payableHolds'][$k]['releasedAt']=gmdate('c');$s['payableHolds'][$k]['releaseReason']='Arrival now falls within approved Soda due date / late-delivery hold resolved';$n++;}return $n;}
function aw_find_soda(array $s,string $entity,string $no):?array{foreach((array)$s['purchaseSodasV2'] as $x)if(is_array($x)&&($x['entity']??'')===$entity&&(string)($x['sodaNo']??'')===$no)return $x;return null;}
function aw_paid(array $s,string $billId):float{$n=0;foreach((array)$s['supplierSettlements'] as $set){if(!is_array($set)||!in_array((string)($set['status']??''),['Posted','Approved / Posted','Approved'],true))continue;foreach((array)($set['allocations']??[]) as $a)if(is_array($a)&&(string)($a['billId']??'')===$billId)$n+=(float)($a['amount']??0);}return round($n,2);}
